// Generated by /ship test audit (Claude Opus 5.5) — 2026-10-15
// Value: protects=the public form's switch to its final screen relies on submitPublicCoachingFormAction returning, word for word, the shell's message for a used, expired or revoked link, while each retryable failure returns a message the shell does not take for a final state;
// fails_when=the action's wording for COACHING_PUBLIC_LINK_SUBMITTED / _EXPIRED / _REVOKED drifts from public-coaching-form-shell (the parent then gets a retry banner and a "Gửi phiếu" that can never succeed), or a retryable failure (a missing or invalid answer, a thrown call, a malformed payload) starts reading as a final state;
// why_new=public-coaching-form-validation.test.tsx feeds the shell's own strings through a stubbed action and every other test mocks the action module, so the two copies of the wording were never compared;
// seam=createSupabaseServerClient is mocked at its module boundary with an rpc stub; no_claim=does not prove submit_public_coaching_form raises these codes (migration 20260815100000) nor the exact Supabase error.message format beyond containing the code
import { afterEach, describe, expect, it, vi } from "vitest";

import { submitPublicCoachingFormAction } from "@/features/coaching/actions/public-coaching-form-actions";
import {
  getPublicFormStateForMessage,
  getPublicFormStateMessage,
} from "@/features/coaching/components/public-coaching-form-shell";

const rpc = vi.hoisted(() => vi.fn());

vi.mock("@/lib/supabase/server", () => ({
  createSupabaseServerClient: vi.fn(async () => ({ rpc })),
}));

afterEach(() => {
  vi.clearAllMocks();
});

const TOKEN = "t".repeat(48);
const ANSWERS = { "00000000-0000-4000-8000-000000000001": "Có" };

describe("submitPublicCoachingFormAction messages and the public form's final screens", () => {
  it.each([
    ["COACHING_PUBLIC_LINK_SUBMITTED", "submitted"],
    ["COACHING_PUBLIC_LINK_EXPIRED", "expired"],
    ["COACHING_PUBLIC_LINK_REVOKED", "revoked"],
  ])("answers %s with the message of the %s screen", async (code, state) => {
    rpc.mockResolvedValue({ data: null, error: { message: code } });

    const result = await submitPublicCoachingFormAction(TOKEN, ANSWERS);

    expect(rpc).toHaveBeenCalledWith("submit_public_coaching_form", { p_answers: ANSWERS, p_token: TOKEN });
    expect(result.status).toBe("error");
    expect(result.message).toBe(getPublicFormStateMessage(state));
    expect(getPublicFormStateForMessage(result.message)).toBe(state);
  });

  it("answers every retryable failure with a message the form keeps on screen", async () => {
    const messages: string[] = [];
    for (const code of ["COACHING_PUBLIC_ANSWER_REQUIRED", "COACHING_PUBLIC_ANSWER_INVALID"]) {
      rpc.mockResolvedValueOnce({ data: null, error: { message: code } });
      messages.push((await submitPublicCoachingFormAction(TOKEN, ANSWERS)).message);
    }
    rpc.mockRejectedValueOnce(new TypeError("fetch failed"));
    messages.push((await submitPublicCoachingFormAction(TOKEN, ANSWERS)).message);
    // Rejected before the RPC: a token shorter than the schema allows.
    messages.push((await submitPublicCoachingFormAction("short", ANSWERS)).message);

    expect(rpc).toHaveBeenCalledTimes(3);
    expect(messages).toHaveLength(4);
    for (const message of messages) {
      expect(message).not.toBe("");
      expect(getPublicFormStateForMessage(message)).toBeNull();
    }
  });
});
